36.         // FRAME_SIZE assume_specification (result > 0).
37.         &&& spec_page_size() > 0
38.         // Every covered bitmap index yields a representable, non-negative frame address.
39.         &&& forall|i: int| self.bitmap@.is_covered(i) ==> {
40.             &&& i >= 0
41.             &&& frame_addr_of(i) <= usize::MAX as int
42.         }
43.     }
