45.     /// Lemma: internal_inv() ==> self@.wf().
46.     proof fn lemma_inv_implies_wf(&self)
47.         requires self.internal_inv(),
48.         ensures self@.wf(),
49.     {
50.         let ps = spec_page_size();
51. 
52.         // Page-alignment of allocated_frames
53.         assert forall|addr: int| self@.allocated_frames.contains(addr) implies addr % ps == 0
54.         by {
55.             let i = choose|i: int| self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
56.             assert(self.bitmap@.set_bits.contains(i));
57.             assert(addr == i * ps);
58.             lemma_mod_multiples_basic(i, ps);
59.         }
60.         // Page-alignment of free_frames
61.         assert forall|addr: int| self@.free_frames.contains(addr) implies addr % ps == 0
62.         by {
63.             let i = choose|i: int| self.bitmap@.is_covered(i) && !self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
64.             assert(addr == i * ps);
65.             lemma_mod_multiples_basic(i, ps);
66.         }
67.         // Disjointness
68.         assert(self@.allocated_frames.disjoint(self@.free_frames)) by {
69.             assert forall|addr: int| !(self@.allocated_frames.contains(addr) && self@.free_frames.contains(addr))
70.             by {
71.                 if self@.allocated_frames.contains(addr) && self@.free_frames.contains(addr) {
72.                     let i_alloc = choose|i: int| self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
73.                     let i_free = choose|i: int| self.bitmap@.is_covered(i) && !self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
74.                     assert(i_alloc * ps == i_free * ps);
75.                     vstd::arithmetic::mul::lemma_mul_is_commutative(i_alloc, ps);
76.                     vstd::arithmetic::mul::lemma_mul_is_commutative(i_free, ps);
77.                     vstd::arithmetic::mul::lemma_mul_equality_converse(ps, i_alloc, i_free);
78.                 }
79.             }
80.         }
81.         // Non-negative allocated addresses
82.         assert forall|addr: int| self@.allocated_frames.contains(addr) implies addr >= 0
83.         by {
84.             let i = choose|i: int| self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
85.             assert(self.bitmap@.set_bits.contains(i));
86.             assert(self.bitmap@.is_covered(i));
87.             assert(i >= 0);
88.             assert(addr == i * ps);
89.             vstd::arithmetic::mul::lemma_mul_nonnegative(i, ps);
90.         }
91.         // Non-negative free addresses
92.         assert forall|addr: int| self@.free_frames.contains(addr) implies addr >= 0
93.         by {
94.             let i = choose|i: int| self.bitmap@.is_covered(i) && !self.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
95.             assert(i >= 0);
96.             assert(addr == i * ps);
97.             vstd::arithmetic::mul::lemma_mul_nonnegative(i, ps);
98.         }
99.     }
